import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
    selector: 'app-checkbox',
    standalone: true,
    imports: [CommonModule],
    template: `
    <div 
      class="w-4 h-4 border rounded flex items-center justify-center cursor-pointer transition-colors"
      [ngClass]="{
        'bg-[#007a91] border-[#007a91]': checked,
        'bg-white border-[#262626]': !checked
      }"
      (click)="toggle($event)"
    >
      <svg *ngIf="checked" xmlns="http://www.w3.org/2000/svg" width="10" height="8" viewBox="0 0 10 8" fill="none">
         <path d="M9 1L3.5 6.5L1 4" stroke="white" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
      </svg>
    </div>
  `
})
export class CheckboxComponent {
    @Input() checked: boolean = false;
    @Output() checkedChange = new EventEmitter<boolean>();

    toggle(event: Event) {
        event.stopPropagation();
        this.checked = !this.checked;
        this.checkedChange.emit(this.checked);
    }
}
